// SPDX-License-Identifier: MIT
// Fogbell Ferry (Prismheart campaign), plain C++17 for the Unreal binding. A port of tools/minigames/fogbell.py
// (unreal-team), which stays the rules authority. Seeding is CPython-compatible (DaedalusPyRandomCore.h,
// "fogbell:<seed>:<difficulty>") and the only draws are randrange, so the same seed is the same tidal flat as the
// Python game. Byte parity goes through engines/unreal/core-test/fogbell_parity.txt (fogbell_core_test.cpp),
// generated by tools/minigames/fogbell_parity.py.
//
// Rules: an S x S flat of integer heights (1..S, the higher of two draws); the ferry starts north-west, the harbour is
// south-east, both on the highest ground; passengers wait on docks (height at least 2). Each turn the ferry moves one
// cell or waits, then the tide stands at turn / TideEvery and floods every cell at or below it. Entering a dock takes
// its passenger aboard; entering the harbour ends the voyage (won with at least Need aboard); a flooded ferry cell
// ends it lost. Score PassengerScore per passenger landed + TideScore per tide step still to come at landing.
#pragma once
#include "DaedalusPyRandomCore.h"
#include <algorithm>
#include <array>
#include <cstdint>
#include <string>
#include <utility>
#include <vector>

namespace daedalus { namespace fogbell {

inline const char* GameId() { return "fogbell"; }
inline const char* Title() { return "Fogbell Ferry"; }

constexpr int PassengerScore = 10, TideScore = 2, TideEvery = 3;
constexpr int MaxSize = 12;

struct Difficulty { const char* Name; int Size; int Passengers; int Need; };
inline const Difficulty* Difficulties()
{
	static const Difficulty Table[] = { { "easy", 7, 3, 2 }, { "normal", 8, 4, 3 }, { "hard", 9, 5, 4 } };
	return Table;
}
constexpr int DifficultyCount = 3;
inline const Difficulty* FindDifficulty(const std::string& Name)
{
	for (int I = 0; I < DifficultyCount; ++I) if (Name == Difficulties()[I].Name) return &Difficulties()[I];
	return nullptr;
}

/** Moves in the rules' order: n, e, s, w, then wait. The BFS expands neighbours in this order, like Python's ORDER. */
enum class Move : int { N = 0, E, S, W, Wait };
constexpr int MoveCount = 5;
inline const char* MoveName(Move M) { static const char* Names[] = { "n", "e", "s", "w", "wait" }; return Names[static_cast<int>(M)]; }
inline bool MoveFromName(const std::string& Name, Move& Out)
{
	for (int I = 0; I < MoveCount; ++I) if (Name == MoveName(static_cast<Move>(I))) { Out = static_cast<Move>(I); return true; }
	return false;
}
inline int MoveDR(Move M) { static const int D[] = { -1, 0, 1, 0, 0 }; return D[static_cast<int>(M)]; }
inline int MoveDC(Move M) { static const int D[] = { 0, 1, 0, -1, 0 }; return D[static_cast<int>(M)]; }

struct Cell { int R = 0, C = 0; bool operator==(const Cell& O) const { return R == O.R && C == O.C; } bool operator!=(const Cell& O) const { return !(*this == O); } };

struct Game
{
	const Difficulty* Diff = nullptr;
	std::vector<std::vector<int>> Heights;
	Cell Ferry, Harbour;
	std::vector<Cell> Passengers;   // in draw order; removed when taken aboard
	int Aboard = 0, Turn = 0;
	int Score = 0; bool Over = false, Won = false;
	pyrandom::PyRandom Rng;

	enum class Act { Ok, BadMove, OffFlat, UnderWater, GameOver };

	int Size() const { return Diff ? Diff->Size : 0; }
	int Tide() const { return Turn / TideEvery; }
	static int TideAt(int AtTurn) { return AtTurn / TideEvery; }
	bool Flooded(int R, int C) const { return Heights[static_cast<size_t>(R)][static_cast<size_t>(C)] <= Tide(); }
	bool Flooded(int R, int C, int AtTurn) const { return Heights[static_cast<size_t>(R)][static_cast<size_t>(C)] <= TideAt(AtTurn); }
	bool Inside(int R, int C) const { return R >= 0 && R < Size() && C >= 0 && C < Size(); }
	int PassengerAt(int R, int C) const
	{
		for (size_t I = 0; I < Passengers.size(); ++I) if (Passengers[I] == Cell{ R, C }) return static_cast<int>(I);
		return -1;
	}

	/** PrismGame.start + Game.setup. False on an unknown difficulty. Draw order: heights row-major (two draws each), then docks. */
	bool Start(std::uint32_t Seed, const std::string& DifficultyName)
	{
		Diff = FindDifficulty(DifficultyName);
		if (!Diff || Diff->Size > MaxSize) return false;
		Rng.Seed(std::string(GameId()) + ":" + std::to_string(Seed) + ":" + DifficultyName);
		Score = 0; Over = Won = false;
		const int S = Diff->Size;
		Heights.assign(static_cast<size_t>(S), std::vector<int>(static_cast<size_t>(S), 0));
		for (int R = 0; R < S; ++R)
			for (int C = 0; C < S; ++C)
			{
				const int A = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
				const int B = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
				Heights[static_cast<size_t>(R)][static_cast<size_t>(C)] = 1 + std::max(A, B);
			}
		Ferry = { 0, 0 }; Harbour = { S - 1, S - 1 };
		Heights[0][0] = S; Heights[static_cast<size_t>(S - 1)][static_cast<size_t>(S - 1)] = S;
		Passengers.clear();
		while (static_cast<int>(Passengers.size()) < Diff->Passengers)
		{
			const int R = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			const int C = static_cast<int>(Rng.RandRange(static_cast<std::uint32_t>(S)));
			const Cell P{ R, C };
			if (P == Ferry || P == Harbour || PassengerAt(R, C) >= 0) continue;
			Passengers.push_back(P);
			int& H = Heights[static_cast<size_t>(R)][static_cast<size_t>(C)];
			H = std::max(H, 2);
		}
		Aboard = 0; Turn = 0;
		return true;
	}

	/** Game.act. `Result` receives the Python result text. */
	Act Step(Move M, std::string& Result)
	{
		if (Over) return Act::GameOver;
		const int R = Ferry.R + MoveDR(M), C = Ferry.C + MoveDC(M);
		if (!Inside(R, C)) return Act::OffFlat;
		if (Flooded(R, C)) return Act::UnderWater;
		Ferry = { R, C };
		bool Picked = false;
		const int P = PassengerAt(R, C);
		if (P >= 0) { Passengers.erase(Passengers.begin() + P); ++Aboard; Picked = true; }
		++Turn;
		const std::string Name = MoveName(M);
		if (Ferry == Harbour)
		{
			const int Left = TideEvery * Size() - Turn;
			Score = PassengerScore * Aboard + TideScore * std::max(0, Left);
			Over = true; Won = Aboard >= Diff->Need;
			Result = Name + ": harbour with " + std::to_string(Aboard) + " aboard, " + (Won ? "the bell rings clear" : "too few lanterns");
			return Act::Ok;
		}
		if (Flooded(R, C)) { Over = true; Won = false; Result = Name + ": the tide takes the ferry"; return Act::Ok; }
		Result = Name + ": " + (Picked ? "lantern aboard" : "open water") + ", tide " + std::to_string(Tide());
		return Act::Ok;
	}

	/**
	 * Game._bfs: shortest flood-aware path (n/e/s/w expansion order) from the ferry to the first goal reached, as the
	 * first move to take. A cell may be entered at step k only if it is still above the tide at turn + k. False when
	 * no goal is reachable.
	 */
	bool FirstStepTo(const std::vector<Cell>& Goals, Move& First) const noexcept
	{
		// Visited/parent tables and two frontier buffers are fixed arrays (MaxSize^2 cells), so the search never
		// allocates (iteration 6). Via: 0 unvisited, 1 the ferry, 2 + move index for the move that reached a cell.
		std::array<std::array<std::uint8_t, MaxSize>, MaxSize> Via{};
		std::array<std::array<Cell, MaxSize>, MaxSize> Prev{};
		std::array<Cell, MaxSize * MaxSize> FrontierA{}, FrontierB{};
		Cell* Frontier = FrontierA.data(); Cell* Next = FrontierB.data();
		int FrontierCount = 1, NextCount = 0;
		Frontier[0] = Ferry;
		Via[static_cast<size_t>(Ferry.R)][static_cast<size_t>(Ferry.C)] = 1;
		for (int Stepk = 1; FrontierCount > 0; ++Stepk)
		{
			NextCount = 0;
			for (int F = 0; F < FrontierCount; ++F)
			{
				const Cell From = Frontier[F];
				for (int I = 0; I < 4; ++I)
				{
					const Move M = static_cast<Move>(I);
					const int R = From.R + MoveDR(M), C = From.C + MoveDC(M);
					if (!Inside(R, C) || Via[static_cast<size_t>(R)][static_cast<size_t>(C)] != 0) continue;
					if (Flooded(R, C, Turn + Stepk)) continue;
					Via[static_cast<size_t>(R)][static_cast<size_t>(C)] = static_cast<std::uint8_t>(2 + I);
					Prev[static_cast<size_t>(R)][static_cast<size_t>(C)] = From;
					bool IsGoal = false;
					for (const Cell& G : Goals) if (G == Cell{ R, C }) { IsGoal = true; break; }
					if (IsGoal)
					{
						// walk back to the ferry; the last move recorded on the way is the first step
						Cell Cur{ R, C };
						int LastMove = I;
						while (Prev[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)] != Ferry)
						{
							Cur = Prev[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)];
							LastMove = Via[static_cast<size_t>(Cur.R)][static_cast<size_t>(Cur.C)] - 2;
						}
						First = static_cast<Move>(LastMove);
						return true;
					}
					Next[NextCount++] = { R, C };
				}
			}
			std::swap(Frontier, Next);
			FrontierCount = NextCount;
		}
		return false;
	}

	/** Game.demo_action: nearest reachable passenger until enough are aboard, then the harbour; wait when stranded. */
	Move DemoAction() const noexcept
	{
		Move First = Move::Wait;
		if (Aboard < Diff->Need && !Passengers.empty() && FirstStepTo(Passengers, First)) return First;
		if (FirstStepTo({ Harbour }, First)) return First;
		if (!Passengers.empty() && FirstStepTo(Passengers, First)) return First;
		return Move::Wait;
	}

	std::string HeightsString() const
	{
		std::string Out;
		for (size_t R = 0; R < Heights.size(); ++R) { if (R) Out.push_back('|'); for (int H : Heights[R]) Out += std::to_string(H); }
		return Out;
	}
	static std::string CellsString(const std::vector<Cell>& V)
	{
		if (V.empty()) return "-";
		std::string Out;
		for (size_t I = 0; I < V.size(); ++I) { if (I) Out.push_back(';'); Out += std::to_string(V[I].R) + "," + std::to_string(V[I].C); }
		return Out;
	}
};

} } // namespace daedalus::fogbell
